#include <functional>
#include <iostream>
#include <limits>
#include <queue>
#include <utility>
#include <vector>
using namespace std;
int main() { int n, m, start, destination; cin >> n >> m >> start >> destination; vector<vector<pair<int, int>>> graph(n + 1); while (m--) { int u, v, w; cin >> u >> v >> w; graph[u].push_back({v, w}); graph[v].push_back({u, w}); } const long long INF = numeric_limits<long long>::max(); vector<long long> distance(n + 1, INF); priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq; distance[start] = 0; pq.push({0, start}); while (!pq.empty()) { auto [current, node] = pq.top(); pq.pop(); if (current != distance[node]) continue; for (auto [next, weight] : graph[node]) { long long candidate = current + weight; if (candidate < distance[next]) { distance[next] = candidate; pq.push({candidate, next}); } } } cout << distance[destination] << '\n'; }
